#!/usr/bin/env python3
from __future__ import annotations

import argparse
import ast
import os
import re
import sys
from dataclasses import dataclass
from pathlib import Path


COMMENT_PREFIX = "; "
KNOWN_SINGLE_OPS = {
    "PART",
    ">PART",
    "ENDPART",
    "PATH",
    "OUTPUT",
    "DEFAULT",
    "OPT",
    "TEXT",
    "DATA",
    "BSS",
    "IFNE",
    "IFEQ",
    "ELSE",
    "ENDC",
    "BASE",
    "IBYTES",
    "END",
}

LABEL_RE = re.compile(r"^[A-Za-z_.][A-Za-z0-9_.]*$")
HEX_RE = re.compile(r"\$([0-9A-Fa-f]+)")
NAME_RE = re.compile(r"\b[A-Za-z_.][A-Za-z0-9_.]*\b")
CONSTANT_LINE_RE = re.compile(r"^[ \t]*[A-Za-z_.][A-Za-z0-9_.]* (?:equ|set)\b", re.IGNORECASE)
NEGATED_LABEL_DIFF_RE = re.compile(
    r"#\s*-\s*([A-Za-z_.][A-Za-z0-9_.]*)\s*\+\s*([A-Za-z_.][A-Za-z0-9_.]*)\b"
)
COMMENTED_IBYTES_RE = re.compile(r";\s*IBYTES\s+(['\"])(.*?)\1\s*$", re.IGNORECASE)


def render_control_char(char: str) -> str:
    code = ord(char)
    names = {
        9: "<TAB>",
        10: "<LF>",
        13: "<CR>",
        27: "<ESC>",
    }
    return names.get(code, f"<0x{code:02X}>")


def sanitize_comment_text(text: str) -> str:
    return "".join(
        render_control_char(char) if (ord(char) < 32 or ord(char) == 127) else char
        for char in text
    )


def render_printable_string(text: str) -> list[str]:
    if not text:
        return []
    if "'" not in text:
        return [f"'{text}'"]
    if '"' not in text:
        return [f'"{text}"']
    return [str(ord(char)) for char in text]


def parse_quoted_literal(text: str) -> tuple[str, str] | None:
    if len(text) < 2 or text[0] not in {"'", '"'}:
        return None

    quote = text[0]
    content: list[str] = []
    index = 1
    while index < len(text):
        char = text[index]
        if char == quote:
            if index + 1 < len(text) and text[index + 1] == quote:
                content.append(char)
                index += 2
                continue
            if index == len(text) - 1:
                return quote, "".join(content)
            return None
        content.append(char)
        index += 1

    return None


def split_operands(text: str) -> list[str]:
    operands: list[str] = []
    current: list[str] = []
    in_quote = False
    quote_char = ""

    for char in text:
        if char in {"'", '"'}:
            if not in_quote:
                in_quote = True
                quote_char = char
            elif char == quote_char:
                in_quote = False
            current.append(char)
            continue

        if char == "," and not in_quote:
            operands.append("".join(current))
            current = []
            continue

        current.append(char)

    operands.append("".join(current))
    return operands


def split_outer_whitespace(text: str) -> tuple[str, str, str]:
    leading_len = len(text) - len(text.lstrip(" \t"))
    trailing_len = len(text) - len(text.rstrip(" \t"))
    trailing_start = len(text) - trailing_len if trailing_len else len(text)
    return text[:leading_len], text[leading_len:trailing_start], text[trailing_start:]


def first_comma_split(text: str) -> tuple[str, str] | None:
    current: list[str] = []
    in_quote = False
    quote_char = ""

    for index, char in enumerate(text):
        if char in {"'", '"'}:
            if not in_quote:
                in_quote = True
                quote_char = char
            elif char == quote_char:
                in_quote = False
        elif char == "," and not in_quote:
            return "".join(current), text[index + 1 :]
        current.append(char)

    return None


def split_comment(line: str) -> tuple[str, str]:
    in_quote = False
    quote_char = ""
    for index, char in enumerate(line):
        if char in {"'", '"'}:
            if not in_quote:
                in_quote = True
                quote_char = char
            elif char == quote_char:
                in_quote = False
        elif char == ";" and not in_quote:
            return line[:index], line[index:]
        elif char == "*" and not in_quote:
            prev_char = line[index - 1] if index > 0 else ""
            next_char = line[index + 1] if index + 1 < len(line) else ""
            if prev_char in {" ", "\t"} and next_char in {"", " ", "\t"}:
                return line[:index], ";" + line[index + 1 :]
    return line, ""


def stringify_comment(text: str) -> str:
    stripped = text.strip()
    return f"{COMMENT_PREFIX}{stripped}" if stripped else COMMENT_PREFIX.rstrip()


def normalize_path_text(path_text: str) -> list[str]:
    normalized = path_text.replace("\\", "/")
    normalized = re.sub(r"^[A-Za-z]:/?", "", normalized)
    return [segment for segment in normalized.split("/") if segment not in {"", "."}]


def resolve_casefold(base: Path, segments: list[str]) -> Path | None:
    current = base
    for segment in segments:
        if segment == "..":
            current = current.parent
            continue
        try:
            children = {child.name.lower(): child for child in current.iterdir()}
        except FileNotFoundError:
            return None
        match = children.get(segment.lower())
        if match is None:
            return None
        current = match
    return current


def path_is_dos_absolute(path_text: str) -> bool:
    return bool(re.match(r"^[A-Za-z]:[\\/]", path_text))


def parse_define(value: str) -> tuple[str, str]:
    if "=" not in value:
        return value, "1"
    name, expr = value.split("=", 1)
    return name.strip(), expr.strip()


class SafeEval(ast.NodeVisitor):
    def __init__(self, names: dict[str, int]):
        self.names = names

    def visit_Expression(self, node: ast.Expression) -> int:
        return self.visit(node.body)

    def visit_Name(self, node: ast.Name) -> int:
        if node.id not in self.names:
            raise ValueError(f"unknown symbol '{node.id}'")
        return self.names[node.id]

    def visit_Constant(self, node: ast.Constant) -> int:
        if not isinstance(node.value, int):
            raise ValueError("non-integer constant")
        return node.value

    def visit_UnaryOp(self, node: ast.UnaryOp) -> int:
        value = self.visit(node.operand)
        if isinstance(node.op, ast.UAdd):
            return value
        if isinstance(node.op, ast.USub):
            return -value
        if isinstance(node.op, ast.Invert):
            return ~value
        raise ValueError("unsupported unary operator")

    def visit_BinOp(self, node: ast.BinOp) -> int:
        left = self.visit(node.left)
        right = self.visit(node.right)
        if isinstance(node.op, ast.Add):
            return left + right
        if isinstance(node.op, ast.Sub):
            return left - right
        if isinstance(node.op, ast.Mult):
            return left * right
        if isinstance(node.op, ast.FloorDiv):
            return left // right
        if isinstance(node.op, ast.Mod):
            return left % right
        if isinstance(node.op, ast.LShift):
            return left << right
        if isinstance(node.op, ast.RShift):
            return left >> right
        if isinstance(node.op, ast.BitAnd):
            return left & right
        if isinstance(node.op, ast.BitOr):
            return left | right
        if isinstance(node.op, ast.BitXor):
            return left ^ right
        raise ValueError("unsupported binary operator")

    def generic_visit(self, node: ast.AST) -> int:
        raise ValueError(f"unsupported syntax: {type(node).__name__}")


@dataclass
class ParsedLine:
    indent: str
    label: str | None
    label_has_colon: bool
    label_sep: str
    opcode: str | None
    opcode_sep: str
    rest: str
    comment: str
    raw: str


class TurboConverter:
    def __init__(
        self,
        source: Path,
        output: Path,
        root: Path,
        defines: dict[str, str],
    ) -> None:
        self.source = source
        self.output = output
        self.root = root
        self.define_exprs = defines
        self.constants: dict[str, int] = {}
        self.current_asset_dir = source.parent
        self.base_register: tuple[str, str] | None = None
        self.base_word_label: str | None = None
        self.dx_width: int | None = None
        self.dx_fill: str | None = None
        self._apply_initial_defines()

    def define_expr_for(self, name: str) -> str | None:
        direct = self.define_exprs.get(name)
        if direct is not None:
            return direct

        lowered = name.lower()
        for define_name, expr in self.define_exprs.items():
            if define_name.lower() == lowered:
                return expr
        return None

    def _apply_initial_defines(self) -> None:
        for name, expr in self.define_exprs.items():
            value = self.evaluate_expr(expr)
            if value is None:
                raise ValueError(f"unable to evaluate -D{name}={expr}")
            self.constants[name] = value

    def evaluate_expr(self, expr: str) -> int | None:
        python_expr = HEX_RE.sub(lambda match: f"0x{match.group(1)}", expr)
        python_expr = python_expr.replace("/", "//")
        try:
            parsed = ast.parse(python_expr, mode="eval")
            return SafeEval(self.constants).visit(parsed)
        except Exception:
            return None

    def parse_line(self, line: str) -> ParsedLine:
        body, comment = split_comment(line)
        indent_len = len(body) - len(body.lstrip(" \t"))
        indent = body[:indent_len]
        content = body[indent_len:]
        if not content.strip():
            return ParsedLine(indent, None, False, "", None, "", "", comment, line)

        label: str | None = None
        label_has_colon = False
        label_sep = ""
        rest_text = content

        label_match = re.match(r"([A-Za-z_.][A-Za-z0-9_.]*):([ \t]*)(.*)$", rest_text, re.S)
        if label_match is not None:
            label = label_match.group(1)
            label_has_colon = True
            label_sep = label_match.group(2)
            rest_text = label_match.group(3)
            if not rest_text.strip():
                return ParsedLine(indent, label, label_has_colon, label_sep, None, "", "", comment, line)

        token_match = re.match(r"(\S+)([ \t]*)(.*)$", rest_text, re.S)
        if token_match is None:
            return ParsedLine(indent, label, label_has_colon, label_sep, None, "", "", comment, line)

        first = token_match.group(1)
        first_sep = token_match.group(2)
        remainder = token_match.group(3)

        if label is None and remainder:
            second_match = re.match(r"(\S+)([ \t]*)(.*)$", remainder, re.S)
            if second_match is not None and second_match.group(1).upper() in {"EQU", "SET"} and LABEL_RE.match(first):
                label = first
                label_sep = first_sep
                first = second_match.group(1)
                first_sep = second_match.group(2)
                remainder = second_match.group(3)

        return ParsedLine(indent, label, label_has_colon, label_sep, first, first_sep, remainder, comment, line)

    def iter_logical_lines(self, text: str) -> list[str]:
        logical_lines: list[str] = []
        current: list[str] = []
        in_quote = False
        quote_char = ""
        in_comment = False
        uses_carriage_returns = "\r" in text
        at_line_start = True
        index = 0
        while index < len(text):
            char = text[index]
            if at_line_start and char in {" ", "\t"}:
                current.append(char)
                index += 1
                continue

            if at_line_start and char == "*" and not in_quote:
                in_comment = True
                current.append(char)
                at_line_start = False
                index += 1
                continue

            if char == ";" and not in_quote:
                in_comment = True
                current.append(char)
                at_line_start = False
                index += 1
                continue

            if char in {"'", '"'} and not in_comment:
                if not in_quote:
                    in_quote = True
                    quote_char = char
                elif char == quote_char:
                    in_quote = False
                current.append(char)
                at_line_start = False
                index += 1
                continue

            if not in_quote and char == "\r":
                logical_lines.append("".join(current))
                current = []
                in_comment = False
                at_line_start = True
                if char == "\r" and index + 1 < len(text) and text[index + 1] == "\n":
                    index += 2
                else:
                    index += 1
                continue

            if not in_quote and not uses_carriage_returns and char == "\n":
                logical_lines.append("".join(current))
                current = []
                in_comment = False
                at_line_start = True
                index += 1
                continue

            current.append(char)
            at_line_start = False
            index += 1

        if current:
            logical_lines.append("".join(current))

        return logical_lines

    def format_comment(self, comment: str) -> str:
        return sanitize_comment_text(comment) if comment else ""

    def line_with(
        self,
        parsed: ParsedLine,
        *,
        label: str | None = None,
        include_label: bool = True,
        label_has_colon: bool | None = None,
        label_sep: str | None = None,
        opcode: str | None = None,
        include_opcode: bool = True,
        opcode_sep: str | None = None,
        rest: str | None = None,
        comment: str | None = None,
    ) -> str:
        label_text = None if not include_label else (parsed.label if label is None else label)
        line = parsed.indent
        if label_text is not None:
            line += label_text
            if parsed.label_has_colon if label_has_colon is None else label_has_colon:
                line += ":"
            line += parsed.label_sep if label_sep is None else label_sep

        opcode_text = None if not include_opcode else (parsed.opcode if opcode is None else opcode)
        if opcode_text is not None:
            line += opcode_text
            opcode_gap = parsed.opcode_sep if opcode_sep is None else opcode_sep
            rest_text = parsed.rest if rest is None else rest
            if opcode_gap or rest_text:
                line += opcode_gap + rest_text

        rendered_comment = parsed.comment if comment is None else comment
        if rendered_comment:
            line += self.format_comment(rendered_comment)
        return line

    def resolve_path(self, path_text: str) -> Path | None:
        segments = normalize_path_text(path_text)
        if not segments:
            return None

        if path_is_dos_absolute(path_text):
            candidates = [
                resolve_casefold(self.root, segments),
                resolve_casefold(self.current_asset_dir, [segments[-1]]),
                resolve_casefold(self.source.parent, [segments[-1]]),
            ]
        else:
            candidates = [
                resolve_casefold(self.current_asset_dir, segments),
                resolve_casefold(self.source.parent, segments),
            ]

        for candidate in candidates:
            if candidate is not None:
                return candidate

        basename = segments[-1].lower()
        nearby = list(self.source.parent.rglob("*"))
        for entry in nearby:
            if entry.is_file() and entry.name.lower() == basename:
                return entry
        for entry in self.root.rglob("*"):
            if entry.is_file() and entry.name.lower() == basename:
                return entry
        return None

    def convert_ibytes(self, parsed: ParsedLine) -> str:
        match = re.match(r"""([ \t]*)(['"])(.*?)\2(.*)""", parsed.rest, re.S)
        if match is None:
            raise ValueError(f"{self.source}: malformed IBYTES: {parsed.raw}")

        source_path = match.group(3)
        trailing = match.group(4)
        resolved = self.resolve_path(source_path)
        rendered_path = (
            os.path.relpath(resolved, self.source.parent).replace("\\", "/")
            if resolved
            else source_path.replace("\\", "/")
        )
        rest = f'{match.group(1)}"{rendered_path}"{trailing}'
        return self.line_with(parsed, label_sep=" " if parsed.label else None, opcode="incbin", rest=rest)

    def rewrite_absolute_zero_trampoline(self, parsed: ParsedLine) -> str | None:
        if parsed.opcode is None:
            return None

        upper = parsed.opcode.upper()
        if upper not in {"JMP", "JSR"}:
            return None

        leading, core, trailing = split_outer_whitespace(parsed.rest)
        if core != "0":
            return None

        return self.line_with(parsed, opcode=parsed.opcode.lower(), rest=f"{leading}0.l{trailing}")

    def rewrite_base_register_operands(self, line: str) -> str:
        if self.base_register is None:
            return line
        register, base_label = self.base_register
        pattern = re.compile(rf"([A-Za-z_.][A-Za-z0-9_.]*(?:[+\-][A-Za-z0-9_.]+)*)\(({register})\)", re.IGNORECASE)

        def replacer(match: re.Match[str]) -> str:
            expr = match.group(1)
            reg = match.group(2)
            if self.expr_references_symbol(expr, base_label) or expr.isdigit():
                return match.group(0)
            return f"{expr}-{base_label}({reg})"

        return pattern.sub(replacer, line)

    def expr_references_symbol(self, expr: str, symbol: str) -> bool:
        return any(match.group(0).lower() == symbol.lower() for match in NAME_RE.finditer(expr))

    def rewrite_base_word_operands(self, parsed: ParsedLine) -> str:
        if self.base_word_label is None or parsed.opcode is None:
            return parsed.raw
        if parsed.opcode.upper() != "DC.W":
            return parsed.raw

        operands = []
        for operand in split_operands(parsed.rest):
            leading, core, trailing = split_outer_whitespace(operand)
            if not core or not NAME_RE.search(core):
                operands.append(core)
                continue
            if self.expr_references_symbol(core, self.base_word_label):
                operands.append(core)
                continue
            rewritten = NAME_RE.sub(
                lambda match: match.group(0)
                if match.group(0).upper() in {"DC", "W"}
                else f"{match.group(0)}-{self.base_word_label}",
                core,
            )
            operands.append(rewritten)

        return self.line_with(
            parsed,
            label_sep=" " if parsed.label else None,
            opcode=parsed.opcode.lower(),
            rest=", ".join(operands),
            comment="",
        )

    def rewrite_ds_with_fill(self, parsed: ParsedLine) -> str | None:
        upper = (parsed.opcode or "").upper()
        if upper not in {"DS.B", "DS.W", "DS.L"} or "," not in parsed.rest:
            return None

        split = first_comma_split(parsed.rest)
        if split is None:
            return None

        count, fill = split
        return self.line_with(
            parsed,
            label_sep=" " if parsed.label else None,
            opcode=f"dcb.{upper[-1].lower()}",
            rest=f"{count},{fill}",
        )

    def rewrite_commented_ibytes(self, parsed: ParsedLine) -> str | None:
        upper = (parsed.opcode or "").upper()
        if upper != "DS.B" or not parsed.comment:
            return None

        match = COMMENTED_IBYTES_RE.fullmatch(parsed.comment)
        if match is None:
            return None

        resolved = self.resolve_path(match.group(2))
        if resolved is None or not resolved.is_file():
            return None

        size = self.evaluate_expr(parsed.rest.strip())
        if size is None or resolved.stat().st_size < size:
            return None

        rendered_path = os.path.relpath(resolved, self.source.parent).replace("\\", "/")
        return self.line_with(
            parsed,
            label_sep=" " if parsed.label else None,
            opcode="incbin",
            rest=f'"{rendered_path}"',
            comment="",
        )

    def normalize_immediate_label_differences(self, line: str) -> str:
        return NEGATED_LABEL_DIFF_RE.sub(lambda match: f"#{match.group(2)}-{match.group(1)}", line)

    def normalize_immediate_char_literals(self, line: str) -> str:
        def replace(match: re.Match[str]) -> str:
            literal = match.group(0)
            body = match.group(2)
            if len(body) != 1:
                return literal
            return f"#{ord(body)}"

        return re.sub(r"#\s*(['\"])(.*?)\1", replace, line, flags=re.S)

    def rewrite_dc_byte_strings(self, parsed: ParsedLine) -> str | None:
        if (parsed.opcode or "").upper() != "DC.B":
            return None

        operands = split_operands(parsed.rest)
        rendered_operands: list[str] = []
        changed = False
        saw_string_operand = False
        for operand in operands:
            leading, core, trailing = split_outer_whitespace(operand)
            quoted = parse_quoted_literal(core)
            if quoted is not None:
                saw_string_operand = True
                quote_char, content = quoted
                if (
                    len(operands) == 1
                    and all(32 <= ord(char) <= 126 for char in content)
                    and quote_char not in content
                ):
                    rendered_operands.append(operand)
                    continue
                pieces: list[str] = []
                printable: list[str] = []
                for char in content:
                    if 32 <= ord(char) <= 126:
                        printable.append(char)
                        continue
                    if printable:
                        pieces.extend(render_printable_string("".join(printable)))
                        printable = []
                    pieces.append(str(ord(char)))
                if printable:
                    pieces.extend(render_printable_string("".join(printable)))

                if not pieces:
                    pieces = ["''"]
                if pieces != [core]:
                    changed = True
                rendered_operands.extend(pieces)
                continue

            value = self.evaluate_expr(core)
            if value is None:
                rendered_operands.append(core)
                continue

            wrapped = value & 0xFF
            normalized = wrapped - 256 if wrapped >= 128 else wrapped
            if value != normalized:
                rendered_operands.append(str(normalized))
                changed = True
                continue

            rendered_operands.append(core)

        if not changed and not (saw_string_operand and len(operands) > 1):
            return None

        return self.line_with(
            parsed,
            label_sep=" " if parsed.label else None,
            opcode=parsed.opcode.lower(),
            rest=", ".join(rendered_operands),
        )

    def handle_dx(self, parsed: ParsedLine, output_lines: list[str]) -> bool:
        upper = (parsed.opcode or "").upper()
        if upper == "DXSET":
            split = first_comma_split(parsed.rest)
            if split is None:
                raise ValueError(f"{self.source}: malformed DXSET: {parsed.raw}")
            width_text, fill_text = split
            width = self.evaluate_expr(width_text)
            if width is None:
                raise ValueError(f"{self.source}: unable to evaluate DXSET width: {parsed.raw}")
            self.dx_width = width
            self.dx_fill = fill_text.strip()
            output_lines.append(f"{parsed.indent}{stringify_comment(f'DXSET {parsed.rest}'.rstrip())}")
            return True

        if upper not in {"DX.B", "DX.W", "DX.L"}:
            return False

        if self.dx_width is None or self.dx_fill is None:
            raise ValueError(f"{self.source}: DX used before DXSET: {parsed.raw}")

        if upper != "DX.B":
            raise ValueError(f"{self.source}: unsupported DX width in: {parsed.raw}")

        quoted = parse_quoted_literal(parsed.rest.strip())
        if quoted is None:
            raise ValueError(f"{self.source}: malformed DX.B: {parsed.raw}")

        _, content = quoted
        fill_count = self.dx_width - len(content)
        if fill_count < 0:
            raise ValueError(f"{self.source}: DX.B content exceeds DXSET width: {parsed.raw}")

        rendered_content = render_printable_string(content) or ["''"]
        output_lines.append(
            self.line_with(
                parsed,
                label_sep=" " if parsed.label else None,
                opcode="dc.b",
                rest=", ".join(rendered_content),
            )
        )
        if fill_count:
            output_lines.append(f"{parsed.indent}dcb.b {fill_count},{self.dx_fill}")
        return True

    def maybe_track_constant(self, parsed: ParsedLine) -> str | None:
        if parsed.opcode is None or parsed.label is None:
            return None
        upper = parsed.opcode.upper()
        if upper not in {"EQU", "SET"}:
            return None

        override = self.define_expr_for(parsed.label)
        expr = override if override is not None else parsed.rest.strip()
        value = self.evaluate_expr(expr)
        if value is not None:
            self.constants[parsed.label] = value

        rendered = parsed.rest if override is None else expr
        return f"{parsed.indent}{parsed.label} {parsed.opcode.lower()} {rendered.strip()}{self.format_comment(parsed.comment)}"

    def handle_conditional(self, parsed: ParsedLine, line_number: int, output_lines: list[str]) -> bool:
        opcode = (parsed.opcode or "").upper()
        if opcode not in {"IFNE", "IFEQ", "ELSE", "ENDC"}:
            return False

        if parsed.label:
            output_lines.append(self.line_with(parsed, include_opcode=False, label_sep="", comment=""))

        if opcode == "IFNE":
            output_lines.append(self.line_with(parsed, include_label=False, opcode="if", rest=parsed.rest))
            return True
        if opcode == "ELSE":
            output_lines.append(self.line_with(parsed, include_label=False, opcode="else", rest=""))
            return True
        if opcode == "IFEQ":
            leading, core, trailing = split_outer_whitespace(parsed.rest)
            output_lines.append(self.line_with(parsed, include_label=False, opcode="if", rest=f"{leading}({core})=0{trailing}"))
            return True
        output_lines.append(self.line_with(parsed, include_label=False, opcode="endif", rest=""))
        return True

    def rewrite_opt(self, parsed: ParsedLine) -> str | None:
        tokens = parsed.rest.split()
        if len(tokens) != 1:
            return None

        token = tokens[0].upper()
        mapping = {
            "O+": '.opt "+oall"',
            "O-": '.opt "~oall"',
            "P+": '.opt "+op"',
            "P-": '.opt "~op"',
        }
        rewritten = mapping.get(token)
        if rewritten is None:
            return None
        return f"{parsed.indent}{rewritten}{self.format_comment(parsed.comment)}"

    def convert(self, text: str) -> str:
        output_lines: list[str] = []
        skip_next_blank_line = False
        for line_number, raw_line in enumerate(self.iter_logical_lines(text), start=1):
            if skip_next_blank_line and raw_line == "":
                skip_next_blank_line = False
                continue
            skip_next_blank_line = False

            stripped_leading = raw_line.lstrip(" \t")
            if stripped_leading.startswith(("*", ";")):
                if any(
                    ord(char) < 32 and char not in {"\t"}
                    for char in stripped_leading[1:]
                ):
                    comment_body = stripped_leading[1:]
                    output_lines.append(
                        f"{raw_line[: len(raw_line) - len(stripped_leading)]}"
                        f"{stringify_comment(sanitize_comment_text(comment_body))}"
                    )
                else:
                    output_lines.append(raw_line)
                continue
            if stripped_leading and (
                stripped_leading[0] in {"'", '"'} or ord(stripped_leading[0]) < 32
            ):
                output_lines.append(
                    f"{raw_line[: len(raw_line) - len(stripped_leading)]}"
                    f"{stringify_comment(sanitize_comment_text(stripped_leading))}"
                )
                continue

            parsed = self.parse_line(raw_line)

            if self.handle_conditional(parsed, line_number, output_lines):
                continue

            if parsed.opcode is None:
                if parsed.label:
                    output_lines.append(
                        self.line_with(
                            parsed,
                            include_opcode=False,
                            label_sep=" " if parsed.comment else "",
                        )
                    )
                elif parsed.comment:
                    output_lines.append(f"{parsed.indent}{self.format_comment(parsed.comment)}")
                else:
                    output_lines.append(raw_line)
                continue

            const_line = self.maybe_track_constant(parsed)
            if const_line is not None:
                output_lines.append(const_line)
                continue

            upper = parsed.opcode.upper()
            if self.handle_dx(parsed, output_lines):
                continue

            trampoline_line = self.rewrite_absolute_zero_trampoline(parsed)
            if trampoline_line is not None:
                output_lines.append(trampoline_line)
                continue

            if upper in {"PART", ">PART", "ENDPART"}:
                if parsed.label:
                    comment = stringify_comment(f"{parsed.opcode} {parsed.rest}".rstrip())
                    output_lines.append(self.line_with(parsed, include_opcode=False, label_sep=" ", comment=comment))
                else:
                    output_lines.append(f"{parsed.indent}{stringify_comment(f'{parsed.opcode} {parsed.rest}'.rstrip())}")
                continue

            if upper == "PATH":
                path_value = parsed.rest.strip().strip("'\"")
                resolved = self.resolve_path(path_value)
                if resolved is not None and resolved.is_dir():
                    self.current_asset_dir = resolved
                details = resolved if resolved is not None else path_value
                output_lines.append(f"{parsed.indent}{stringify_comment(f'PATH {details}')}")
                continue

            if upper == "OPT":
                rewritten_opt = self.rewrite_opt(parsed)
                if rewritten_opt is not None:
                    output_lines.append(rewritten_opt)
                else:
                    output_lines.append(f"{parsed.indent}{stringify_comment(f'{parsed.opcode} {parsed.rest}'.rstrip())}")
                continue

            if upper in {"OUTPUT", "DEFAULT"}:
                output_lines.append(f"{parsed.indent}{stringify_comment(f'{parsed.opcode} {parsed.rest}'.rstrip())}")
                continue

            if upper in {"TEXT", "DATA", "BSS"}:
                directive = upper.lower()
                directive_line = self.line_with(parsed, opcode=directive, rest="")
                if (
                    len(output_lines) >= 2
                    and output_lines[-1] == ""
                    and CONSTANT_LINE_RE.match(output_lines[-2]) is not None
                ):
                    output_lines.pop()
                    constant_line = output_lines.pop()
                    output_lines.append(directive_line)
                    output_lines.append(constant_line)
                    output_lines.append("")
                    skip_next_blank_line = True
                else:
                    output_lines.append(directive_line)
                continue

            if upper == "BASE":
                rest = parsed.rest.strip()
                if rest.upper() == "A6,OFF":
                    self.base_register = None
                elif rest.upper().startswith("A6,"):
                    self.base_register = ("a6", rest.split(",", 1)[1].strip())
                elif rest.upper() == "DC.W,OFF":
                    self.base_word_label = None
                elif rest.upper().startswith("DC.W,"):
                    self.base_word_label = rest.split(",", 1)[1].strip()
                if (
                    len(output_lines) >= 4
                    and output_lines[-1] == ""
                    and output_lines[-2] == ""
                    and output_lines[-3] == ""
                    and output_lines[-4].lstrip().startswith("; ENDPART")
                ):
                    output_lines.pop()
                output_lines.append(f"{parsed.indent}{stringify_comment(f'BASE {rest}')}")
                continue

            if upper == "IBYTES":
                output_lines.append(self.convert_ibytes(parsed))
                continue

            if upper in {"DCB.B", "DCB.W", "DCB.L"} and "," not in parsed.rest:
                leading, core, trailing = split_outer_whitespace(parsed.rest)
                output_lines.append(
                    self.line_with(
                        parsed,
                        label_sep=" " if parsed.label else None,
                        opcode=parsed.opcode.lower(),
                        rest=f"{leading}{core},0{trailing}",
                    )
                )
                continue

            ds_with_fill = self.rewrite_ds_with_fill(parsed)
            if ds_with_fill is not None:
                output_lines.append(ds_with_fill)
                continue

            commented_ibytes = self.rewrite_commented_ibytes(parsed)
            if commented_ibytes is not None:
                output_lines.append(commented_ibytes)
                continue

            dc_byte_strings = self.rewrite_dc_byte_strings(parsed)
            if dc_byte_strings is not None:
                output_lines.append(dc_byte_strings)
                continue

            transformed = self.line_with(parsed, comment="")
            if self.base_word_label is not None and upper == "DC.W":
                transformed = self.rewrite_base_word_operands(parsed)
            elif self.base_register is not None:
                transformed = self.rewrite_base_register_operands(transformed)
            transformed = self.normalize_immediate_label_differences(transformed)
            transformed = self.normalize_immediate_char_literals(transformed)
            if parsed.comment:
                transformed += self.format_comment(parsed.comment)

            output_lines.append(transformed)

        return "\n".join(output_lines) + "\n"


def default_output_path(source: Path) -> Path:
    if source.name.endswith(".original.S"):
        stem = source.name[: -len(".original.S")]
        return source.with_name(f"{stem}.converted.S")
    return source.with_name(f"{source.stem}.converted{source.suffix}")


def main() -> int:
    parser = argparse.ArgumentParser(description="Convert TurboAsm-flavoured 68k sources into the repo's shared rmac-build syntax.")
    parser.add_argument("source", type=Path, help="TurboAsm-style source file to convert")
    parser.add_argument("-o", "--output", type=Path, help="Destination file")
    parser.add_argument(
        "--root",
        type=Path,
        default=Path.cwd(),
        help="Workspace root used to resolve DOS-style PATH/IBYTES references",
    )
    parser.add_argument(
        "-D",
        "--define",
        action="append",
        default=[],
        metavar="NAME=VALUE",
        help="Override an assembly constant before conditional handling",
    )
    args = parser.parse_args()

    defines = dict(parse_define(item) for item in args.define)
    source = args.source.resolve()
    output = (
        args.output.resolve()
        if args.output is not None
        else default_output_path(source)
    )
    root = args.root.resolve()

    converter = TurboConverter(
        source=source,
        output=output,
        root=root,
        defines=defines,
    )

    with source.open("r", encoding="latin-1", newline="") as handle:
        text = handle.read()
    converted = converter.convert(text)

    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(converted, encoding="latin-1")
    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except ValueError as exc:
        print(exc, file=sys.stderr)
        raise SystemExit(1)

