#!/usr/bin/env python3
"""prgtool -- small helper for Commodore PRG files (C16 / +4 / C64 layout).

A PRG is a 2-byte little-endian load address followed by the bytes that go to
memory starting at that address.  All addresses below are *machine* addresses
(what the CPU sees), not file offsets, so they match Ghidra and ACME listings.

  prgtool.py info   FILE.prg                      header, BASIC lines, SYS target
  prgtool.py dump   FILE.prg [START [LEN]]        hex dump in machine addresses
  prgtool.py patch  IN.prg OUT.prg ADDR OLD NEW   binary patch, verifies OLD first
  prgtool.py extend IN.prg OUT.prg HEX            append bytes after the end (a "code cave")
  prgtool.py header RAW.bin OUT.prg [LOAD]        add a load-address header (default 1001)
  prgtool.py strip  IN.prg OUT.bin                remove the header
  prgtool.py diff   A.prg B.prg                   list differing bytes by machine address

Numbers are hexadecimal; a leading $ or 0x is accepted.  OLD/NEW are byte strings
such as 15 or EE15FF (spaces allowed).
"""
import sys

# BASIC 2 / 3.5 tokens $80-$A2 (identical in both); anything else prints as {$xx}
TOKENS = {
    0x80: "END", 0x81: "FOR", 0x82: "NEXT", 0x83: "DATA", 0x84: "INPUT#",
    0x85: "INPUT", 0x86: "DIM", 0x87: "READ", 0x88: "LET", 0x89: "GOTO",
    0x8A: "RUN", 0x8B: "IF", 0x8C: "RESTORE", 0x8D: "GOSUB", 0x8E: "RETURN",
    0x8F: "REM", 0x90: "STOP", 0x91: "ON", 0x92: "WAIT", 0x93: "LOAD",
    0x94: "SAVE", 0x95: "VERIFY", 0x96: "DEF", 0x97: "POKE", 0x98: "PRINT#",
    0x99: "PRINT", 0x9A: "CONT", 0x9B: "LIST", 0x9C: "CLR", 0x9D: "CMD",
    0x9E: "SYS", 0x9F: "OPEN", 0xA0: "CLOSE", 0xA1: "GET", 0xA2: "NEW",
}


def num(s):
    s = s.strip().lower()
    if s.startswith("$"):
        s = s[1:]
    if s.startswith("0x"):
        s = s[2:]
    return int(s, 16)


def hexbytes(s):
    s = s.replace(" ", "")
    if s.lower().startswith("0x"):
        s = s[2:]
    return bytes.fromhex(s)


def read_prg(path):
    data = open(path, "rb").read()
    if len(data) < 3:
        sys.exit("%s: too short to be a PRG" % path)
    return data[0] | data[1] << 8, bytearray(data[2:])


def write_prg(path, load, body):
    open(path, "wb").write(bytes([load & 0xFF, load >> 8]) + bytes(body))


def basic_lines(load, body):
    """Yield (line_number, detokenised_text, sys_target_or_None)."""
    pos = 0
    while pos + 4 <= len(body):
        link = body[pos] | body[pos + 1] << 8
        if link == 0:
            return
        lineno = body[pos + 2] | body[pos + 3] << 8
        p = pos + 4
        text, sys_target = "", None
        while p < len(body) and body[p] != 0:
            b = body[p]
            if b in TOKENS:
                text += TOKENS[b] + " "
                if b == 0x9E:
                    digits = ""
                    q = p + 1
                    while q < len(body) and body[q] == 0x20:
                        q += 1
                    while q < len(body) and 0x30 <= body[q] <= 0x39:
                        digits += chr(body[q])
                        q += 1
                    if digits:
                        sys_target = int(digits)
            elif b >= 0x80:
                text += "{$%02X}" % b
            else:
                text += chr(b)
            p += 1
        yield lineno, text.strip(), sys_target
        nxt = link - load
        if nxt <= pos:
            return
        pos = nxt


def hexdump(load, body, start, length):
    for off in range(start - load, min(start - load + length, len(body)), 16):
        chunk = body[off:off + 16]
        asc = "".join(chr(c) if 32 <= c < 127 else "." for c in chunk)
        print("%04X  %-47s  %s" % (load + off, " ".join("%02X" % c for c in chunk), asc))


def cmd_info(path):
    load, body = read_prg(path)
    end = load + len(body) - 1
    print("file        : %s" % path)
    print("load address: $%04X (%d)" % (load, load))
    print("payload     : %d bytes, ends at $%04X   (Ghidra import: File Offset 2, Length 0x%X)"
          % (len(body), end, len(body)))
    sys_target = None
    for lineno, text, tgt in basic_lines(load, body):
        print("BASIC       : %d %s" % (lineno, text))
        sys_target = sys_target or tgt
    if sys_target is not None:
        print("SYS target  : %d = $%04X  <- machine code entry point" % (sys_target, sys_target))
    else:
        print("SYS target  : none found (no BASIC stub, or entry is elsewhere)")
    print()
    hexdump(load, body, load, min(len(body), 96))


def cmd_dump(path, args):
    load, body = read_prg(path)
    start = num(args[0]) if args else load
    length = num(args[1]) if len(args) > 1 else len(body)
    hexdump(load, body, start, length)


def cmd_patch(src, dst, addr, old, new):
    load, body = read_prg(src)
    addr, old, new = num(addr), hexbytes(old), hexbytes(new)
    if len(old) != len(new):
        sys.exit("OLD and NEW must be the same length (this tool never moves code)")
    off = addr - load
    if off < 0 or off + len(old) > len(body):
        sys.exit("$%04X is outside the file ($%04X-$%04X)" % (addr, load, load + len(body) - 1))
    have = bytes(body[off:off + len(old)])
    if have != old:
        sys.exit("refusing to patch: $%04X holds %s, expected %s" % (addr, have.hex(" "), old.hex(" ")))
    body[off:off + len(new)] = new
    write_prg(dst, load, body)
    print("patched $%04X: %s -> %s  (%s)" % (addr, old.hex(" "), new.hex(" "), dst))


def cmd_extend(src, dst, data):
    """Append bytes after the last byte of the program (a 'code cave')."""
    load, body = read_prg(src)
    new = hexbytes(data)
    at = load + len(body)
    body += new
    write_prg(dst, load, body)
    print("appended %d byte(s) at $%04X-$%04X  (%s)" % (len(new), at, at + len(new) - 1, dst))


def cmd_header(src, dst, load="1001"):
    write_prg(dst, num(load), open(src, "rb").read())
    print("%s: added load address $%04X" % (dst, num(load)))


def cmd_strip(src, dst):
    load, body = read_prg(src)
    open(dst, "wb").write(bytes(body))
    print("%s: %d bytes (load address $%04X removed)" % (dst, len(body), load))


def cmd_diff(a, b):
    la, ba = read_prg(a)
    lb, bb = read_prg(b)
    if la != lb:
        print("load addresses differ: $%04X vs $%04X" % (la, lb))
    n = max(len(ba), len(bb))
    diffs = [i for i in range(n) if (ba[i] if i < len(ba) else None) != (bb[i] if i < len(bb) else None)]
    for i in diffs:
        x = "%02X" % ba[i] if i < len(ba) else "--"
        y = "%02X" % bb[i] if i < len(bb) else "--"
        print("$%04X: %s -> %s" % (la + i, x, y))
    print("%d byte(s) differ" % len(diffs))
    return 1 if diffs else 0


def main(argv):
    if len(argv) < 3 or argv[1] in ("-h", "--help"):
        print(__doc__)
        return 0
    cmd, args = argv[1], argv[2:]
    try:
        if cmd == "info":
            cmd_info(args[0])
        elif cmd == "dump":
            cmd_dump(args[0], args[1:])
        elif cmd == "patch":
            cmd_patch(*args)
        elif cmd == "extend":
            cmd_extend(*args)
        elif cmd == "header":
            cmd_header(*args)
        elif cmd == "strip":
            cmd_strip(*args)
        elif cmd == "diff":
            return cmd_diff(*args)
        else:
            sys.exit("unknown command: " + cmd)
    except TypeError:
        sys.exit("wrong number of arguments for '%s' -- see --help" % cmd)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

